  function qualityEligible(obs,targetPos){const observer=String(obs.observer||'').toLowerCase();if(!observer||!targetPos)return false;if(targetPos.supervisorUsername)return String(targetPos.supervisorUsername).toLowerCase()===observer;const op=bestPositionFor(observer,targetPos.division);return Boolean(op&&rankOf(op.level)===Math.max(0,rankOf(targetPos.level)-1)&&((op.division==='Semua Divisi')||op.division===targetPos.division))}
  async function refreshPerformanceSummary(uname,pos=bestPositionFor(uname),month=monthKey()){
    if(!uname||!pos)return null;
    const [jSnap,oSnap,kSnap]=await Promise.all([
      db.ref(`${ROOT}/journal_by_person/${safeKey(uname)}`).limitToLast(70).once('value').catch(()=>null),
      db.ref(`${ROOT}/observations_by_person/${safeKey(uname)}`).limitToLast(100).once('value').catch(()=>null),
      db.ref(`${ROOT}/objectives_by_person/${safeKey(uname)}`).limitToLast(60).once('value').catch(()=>null)
    ]);
    const role=normalizeRole(pos.sourceRole||''),journals=snapRows(jSnap).filter(j=>String(j.date||'').startsWith(month)&&(j.positionId===pos.id||((j.role===role||!j.role)&&j.level===pos.level&&j.division===pos.division)));
    const observations=snapRows(oSnap).filter(o=>String(o.date||'').startsWith(month)&&(o.observedPositionId===pos.id||(o.observedRole===role&&o.division===pos.division))&&Number.isFinite(Number(o.qualityScore))&&qualityEligible(o,pos));
    const objectives=snapRows(kSnap).filter(o=>o.period===month&&(o.positionId===pos.id||normalizeRole(o.role)===role));
    const exVals=journals.map(j=>Number(j.completionPercent)).filter(Number.isFinite),qVals=observations.map(o=>Number(o.qualityScore)).filter(Number.isFinite),rVals=objectives.map(objectiveAchievement).filter(Number.isFinite);
    const execution=exVals.length?Math.round(exVals.reduce((a,b)=>a+b,0)/exVals.length):null;
    const quality=qVals.length?Math.round(qVals.reduce((a,b)=>a+b,0)/qVals.length):null;
    const result=rVals.length?Math.round(rVals.reduce((a,b)=>a+b,0)/rVals.length):null;
    const weights=SCORE_WEIGHTS[pos.level]||SCORE_WEIGHTS['staf-mula'],available=[['execution',execution],['quality',quality],['result',result]].filter(([,v])=>v!==null);
    const usedWeight=available.reduce((s,[k])=>s+weights[k],0),score=usedWeight?Math.round(available.reduce((s,[k,v])=>s+v*weights[k],0)/usedWeight):null;
    const official=execution!==null&&quality!==null&&result!==null&&observations.length>=3;
    const u=userByUsername(uname),summary={username:uname,name:nameOf(u)||uname,role,positionId:pos.id,positionTitle:pos.title,level:pos.level,division:pos.division,execution,quality,result,score,journalCount:journals.length,observationCount:observations.length,objectiveCount:objectives.length,official,weights,formula:`Pelaksanaan ${weights.execution}% • Mutu ${weights.quality}% • Hasil/KPI ${weights.result}%`,updatedAt:nowIso()};
    await db.ref(`${ROOT}/performance_monthly/${month}/${positionGroupKey(pos)}/${safeKey(uname)}`).set(summary).catch(()=>{});
    return summary
  }
