    const officialPeers=peers.filter(x=>x.official&&Number.isFinite(Number(x.score))).sort((a,b)=>b.score-a.score),idx=officialPeers.findIndex(x=>String(x.username).toLowerCase()===username()),rank=mine.official&&idx>=0?`Peringkat #${idx+1} dari ${officialPeers.length}`:'Penilaian sementara';
