  function objectiveAchievement(x){
    if(x?.target===null||x?.target===undefined||x?.target===''||x?.actual===null||x?.actual===undefined||x?.actual==='')return null;
    const target=Number(x.target),actual=Number(x.actual);
    if(!Number.isFinite(target)||target===0||!Number.isFinite(actual))return null;
    const raw=x.direction==='at_most'?(actual<=target?100:(target/actual*100)):(actual/target*100);
    return Math.max(0,Math.min(100,Math.round(raw)));
  }
