  async function saveObjective(){
    const id=$('objectiveId').value||db.ref(`${ROOT}/objectives`).push().key,title=$('objectiveTitle').value.trim(),pos=selectedObjectiveTargetPosition();
    if(!title||!pos){toast('Objektif dan pemilik wajib diisi.');return}
    const role=normalizeRole(pos.sourceRole),kpis=roleProfile(role).kpis||[],kpi=kpis.find(x=>x.id===$('objectiveKpi').value),old=data.objectives.find(x=>x.id===id)||{};
    const payload={title,period:$('objectivePeriod').value||monthKey(),username:pos.username,name:nameOf(userByUsername(pos.username))||pos.username,role,positionId:pos.id,positionTitle:pos.title,level:pos.level,division:pos.division,kpiId:kpi?.id||$('objectiveKpi').value,kpiName:kpi?.name||$('objectiveKpiName').value||'KPI',target:Number($('objectiveTarget').value||0),actual:$('objectiveActual').value===''?null:Number($('objectiveActual').value),unit:$('objectiveUnit').value.trim()||'%',direction:$('objectiveDirection').value,initiative:$('objectiveInitiative').value.trim(),createdAt:old.createdAt||nowIso(),createdBy:old.createdBy||createdMeta(),updatedAt:nowIso(),updatedBy:createdMeta()};
    payload.achievementPercent=objectiveAchievement(payload);payload.status=objectiveStatus(payload);
    showLoader('Menyimpan objective...');try{
      await db.ref(`${ROOT}/objectives/${id}`).set(payload);await db.ref(`${ROOT}/objectives_by_person/${safeKey(pos.username)}/${id}`).set(payload);
      if(old.username&&old.username!==pos.username)await db.ref(`${ROOT}/objectives_by_person/${safeKey(old.username)}/${id}`).remove();
      deleteCache('objectives');closeForm();toast('Objektif tersimpan.');await refreshPerformanceSummary(pos.username,pos,payload.period);if(currentView==='objectives'){await ensureForView('objectives',true);renderObjectives()}
    }finally{hideLoader()}
  }
  function renderObjectives(){
    const q=String($('objectiveSearch')?.value||'').toLowerCase(),period=$('objectivePeriodFilter')?.value||'',status=$('objectiveStatusFilter')?.value||'';
    const rows=scoped('objectives').filter(x=>(!q||`${x.title} ${x.kpiName} ${x.name}`.toLowerCase().includes(q))&&(!period||x.period===period)&&(!status||objectiveStatus(x)===status));
    $('objectiveList').innerHTML=rows.length?rows.map(x=>{const a=objectiveAchievement(x),s=objectiveStatus(x),cls=s==='tercapai'?'green':s==='belum'?'red':'gold';return recordCard({chips:[`<span class="chip ${cls}">${s==='tercapai'?'Tercapai':s==='belum'?'Belum Tercapai':'Aktif'}</span>`,`<span class="chip blue">${esc(roleLabel(x.role))}</span>`],date:fmtMonth(x.period),title:x.title,desc:`${x.kpiName||'KPI'} • Target ${x.direction==='at_most'?'≤':'≥'} ${x.target??'–'} ${x.unit||''} • Aktual ${x.actual??'–'} ${x.unit||''}`,foot:`<div class="objective-progress"><i style="--pct:${a??0}%"></i><b>${a===null?'Belum diisi':a+'%'}</b></div><span>${esc(x.name||x.username||'')}</span>`,onclick:`Operational.openObjectiveForm('${esc(x.id)}')`})}).join(''):empty('Belum ada Objektif untuk lingkup ini.')
  }

