  async function uploadEvidence(file,id){if(!file)return'';const ext=(file.name.split('.').pop()||'jpg').replace(/[^a-z0-9]/gi,'');const r=storage.ref(`cahaya_app/operasional/bukti_observasi/${id}/${Date.now()}.${ext}`),s=await r.put(file);return s.ref.getDownloadURL()}
  async function saveObservation(){const id=$('observationId').value||db.ref(`${ROOT}/observations`).push().key,subject=$('observationSubject').value.trim(),person=$('observationPerson').value;if(!subject){toast('Objek observasi wajib diisi.');return}const old=data.observations.find(x=>x.id===id)||{},pu=userByUsername(person),targetPos=bestPositionFor(person,$('observationDivision').value),signal=document.querySelector('input[name="observationSignal"]:checked')?.value||'green',rating=Number(document.querySelector('input[name="observationQuality"]:checked')?.value||4),qualityScore=rating*20;showLoader('Menyimpan observasi...');try{let evidenceUrl=old.evidenceUrl||'',file=$('observationEvidence').files?.[0];if(file)try{evidenceUrl=await uploadEvidence(file,id)}catch(e){console.warn(e)}let followupId=old.followupId||'',make=$('observationMakeFollowup').checked,pic=$('observationFollowPic').value,deadline=$('observationFollowDeadline').value;if(make){if(!followupId)followupId=db.ref(`${ROOT}/followups`).push().key;const f={task:`Tindak lanjut observasi: ${subject}`,sourceType:'observasi',sourceId:id,sourceTitle:subject,division:$('observationDivision').value,pic,picName:nameOf(userByUsername(pic))||pic,deadline,priority:signal==='red'?'tinggi':'sedang',status:'baru',createdAt:old.createdAt||nowIso(),createdBy:createdMeta(),updatedAt:nowIso(),updatedBy:createdMeta()};await db.ref(`${ROOT}/followups/${followupId}`).set(f);if(pic)await db.ref(`${ROOT}/followups_by_pic/${safeKey(pic)}/${followupId}`).set(f);if(pic&&pic!==old.followupPic)await notifyUser(pic,'Tindak Lanjut Observasi',`${displayName()} membuat tindak lanjut: ${subject}`,'main-dashboard.html?operasional=followups')}else if(followupId){await db.ref(`${ROOT}/followups/${followupId}`).remove();if(old.followupPic)await db.ref(`${ROOT}/followups_by_pic/${safeKey(old.followupPic)}/${followupId}`).remove();followupId=''}const payload={date:$('observationDate').value,targetType:$('observationTarget').value,division:$('observationDivision').value,observedPerson:person,observedPersonName:nameOf(pu)||person,observedPositionId:targetPos?.id||'',observedPositionTitle:targetPos?.title||'',observedRole:targetPos?.sourceRole||'',subject,signal,qualityRating:rating,qualityScore,finding:$('observationFinding').value.trim(),recommendation:$('observationRecommendation').value.trim(),evidenceUrl,observer:username(),observerName:displayName(),observerPositionId:activePosition.id,observerPositionTitle:activePosition.title,observerLevel:currentLevel(),qualityEligible:person?Boolean(targetPos&&((targetPos.supervisorUsername&&String(targetPos.supervisorUsername).toLowerCase()===username())||(!targetPos.supervisorUsername&&rankOf(currentLevel())===Math.max(0,rankOf(targetPos.level)-1)))):false,followupId,followupPic:make?pic:'',followupDeadline:make?deadline:'',createdAt:old.createdAt||nowIso(),createdBy:old.createdBy||createdMeta(),updatedAt:nowIso(),updatedBy:createdMeta()};await db.ref(`${ROOT}/observations/${id}`).set(payload);if(person){await db.ref(`${ROOT}/observations_by_person/${safeKey(person)}/${id}`).set(payload);await refreshPerformanceSummary(person,targetPos||bestPositionFor(person),String(payload.date).slice(0,7))}deleteCache('observations');deleteCache('followups');closeForm();toast('Observasi berhasil disimpan.')}finally{hideLoader()}}
