  async function saveReport(){const id=db.ref(`${ROOT}/reports`).push().key,m=reportMetrics($('reportStart').value,$('reportEnd').value),payload={reportType:$('reportType').value,title:`${$('reportType').value} • ${$('reportPeriodLabel').value}`,period:$('reportPeriod').value,periodLabel:$('reportPeriodLabel').value,division:currentDivision(),positionId:activePosition.id,positionTitle:activePosition.title,destination:$('reportDestination').value,destinationUsername:activePosition.supervisorUsername||'',summary:$('reportSummary').value.trim(),achievements:$('reportAchievements').value.trim(),obstacles:$('reportObstacles').value.trim(),priorities:$('reportPriorities').value.trim(),support:$('reportSupport').value.trim(),metrics:m,author:username(),authorName:displayName(),authorRole:activeRole,authorLevel:currentLevel(),createdAt:nowIso(),createdBy:createdMeta(),updatedAt:nowIso()};await db.ref(`${ROOT}/reports/${id}`).set(payload);if(payload.destinationUsername)await notifyUser(payload.destinationUsername,'Laporan Operasional Baru',`${payload.authorName} mengirim ${payload.reportType} • ${payload.periodLabel}`,'main-dashboard.html?operasional=reports');deleteCache('reports');closeForm();toast('Laporan operasional disimpan.')}
  function openReportDetail(id){const x=data.reports.find(a=>a.id===id);if(!x)return;const m=x.metrics||{};$('detailKicker').textContent='LAPORAN OPERASIONAL';$('detailTitle').textContent=x.title||'Laporan';$('detailBody').innerHTML=`<article class="report-preview"><h2>${esc(x.reportType||'Laporan')}</h2><div class="report-meta">${esc(x.periodLabel||'-')} • ${esc(x.division||'-')} • kepada ${esc(x.destination||'-')}</div><div class="report-section"><div class="report-kpis"><div class="report-kpi"><span>Tugas</span><b>${m.tasks??0}</b></div><div class="report-kpi"><span>Observasi</span><b>${m.observations??0}</b></div><div class="report-kpi"><span>Rapat</span><b>${m.meetings??0}</b></div><div class="report-kpi"><span>Tindak Lanjut</span><b>${m.followups??0}</b></div></div></div><div class="report-section"><h3>Executive Summary</h3><p>${esc(x.summary||'-')}</p></div><div class="report-section"><h3>Capaian Positif</h3><p>${esc(x.achievements||'-')}</p></div><div class="report-section"><h3>Hambatan / Risiko</h3><p>${esc(x.obstacles||'-')}</p></div><div class="report-section"><h3>Prioritas Berikutnya</h3><p>${esc(x.priorities||'-')}</p></div><div class="report-section"><h3>Dukungan yang Dibutuhkan</h3><p>${esc(x.support||'-')}</p></div></article><div class="form-actions"><button class="btn soft" onclick="Operational.closeDetail()">Tutup</button><button class="btn primary" onclick="window.print()">Cetak / PDF</button></div>`;modalOpen('detailModal')}

  function renderJournals(){const q=String($('journalSearch')?.value||'').toLowerCase(),scope=$('journalScopeFilter')?.value||'saya';const arr=data.journals.filter(x=>(scope==='tim'?visibleRecord(x,'journals'):String(x.username||'').toLowerCase()===username())&&(!q||[x.name,x.positionTitle,x.division,...(x.items||[]).map(i=>i.title)].join(' ').toLowerCase().includes(q)));$('journalList').innerHTML=arr.length?arr.map(x=>recordCard({chips:[`<span class="chip blue">${esc(x.positionTitle||x.name||x.username||'-')}</span>`,`<span class="chip ${Number(x.completionPercent)>=80?'green':Number(x.completionPercent)>=60?'gold':'red'}">${Number.isFinite(Number(x.completionPercent))?x.completionPercent+'%':'–'}</span>`],date:fmtDate(x.date),title:`Jurnal ${esc(x.name||x.username||'-')}`,desc:`${x.completedCount||0}/${x.expectedCount||0} jobdesk selesai • ${x.hinderedCount||0} kendala`,foot:`<span>${esc(x.division||'-')}</span><span>${(x.items||[]).length} item</span>`})).join(''):empty('Belum ada jurnal pelaksanaan.')}
  async function openJournalForm(){showLoader('Menyiapkan jobdesk hari ini...');try{await buildTodayJobs();if(!todayJobs.length){toast('Belum ada jobdesk untuk posisi aktif hari ini.');return}const oldMap=new Map((todayJournal?.items||[]).map(i=>[i.id,i]));$('formKicker').textContent='JURNAL PELAKSANAAN';$('formTitle').textContent=`${activePosition.title} • ${fmtDate(today())}`;$('formBody').innerHTML=`<div class="journal-duty-list">${todayJobs.map((j,i)=>{const o=oldMap.get(j.id)||j;return `<div class="journal-duty" data-job-id="${esc(j.id)}" data-source="${esc(j.sourceType)}" data-source-id="${esc(j.sourceId||'')}"><div class="journal-duty-head"><span><b>${i+1}. ${esc(j.title)}</b><small>${esc(j.time||'Hari ini')} • ${esc(j.standard||'')}</small></span></div><div class="journal-status">${[['selesai','✓ Selesai'],['kendala','⚠ Ada Kendala'],['belum','○ Belum']].map(([v,l])=>`<label><input type="radio" name="journal_${i}" value="${v}" ${(o.status||'belum')===v?'checked':''}><span>${l}</span></label>`).join('')}</div><textarea placeholder="Catatan hanya bila diperlukan…">${esc(o.note||'')}</textarea><label class="journal-escalate"><input type="checkbox" class="jd-followup" ${o.makeFollowup?'checked':''}> Jika ada kendala, jadikan tindak lanjut operasional</label></div>`}).join('')}</div><div class="form-actions"><button class="btn soft" onclick="Operational.closeForm()">Batal</button><button class="btn green" onclick="Operational.saveJournal()">Simpan Jurnal Hari Ini</button></div>`;modalOpen('formModal')}finally{hideLoader()}}
  async function saveJournal(){const items=[...document.querySelectorAll('.journal-duty')].map((row,i)=>({id:row.dataset.jobId,title:todayJobs[i]?.title||'',time:todayJobs[i]?.time||'',standard:todayJobs[i]?.standard||'',sourceType:row.dataset.source,sourceId:row.dataset.sourceId,status:row.querySelector(`input[name="journal_${i}"]:checked`)?.value||'belum',note:row.querySelector('textarea').value.trim(),makeFollowup:Boolean(row.querySelector('.jd-followup')?.checked)})),expected=items.length,completed=items.filter(x=>x.status==='selesai').length,hindered=items.filter(x=>x.status==='kendala').length,pct=expected?Math.round(completed/expected*100):null,key=`${today()}_${safeKey(activePosition.id)}`,payload={date:today(),username:username(),name:displayName(),role:activeRole,level:currentLevel(),division:currentDivision(),positionId:activePosition.id,positionTitle:activePosition.title,items,expectedCount:expected,completedCount:completed,hinderedCount:hindered,completionPercent:pct,updatedAt:nowIso(),createdAt:todayJournal?.createdAt||nowIso()};showLoader('Menyimpan jurnal pelaksanaan...');try{await db.ref(`${ROOT}/journals/${safeKey(username())}_${key}`).set(payload);await db.ref(`${ROOT}/journal_by_person/${safeKey(username())}/${key}`).set(payload);for(const i of items.filter(x=>x.sourceType==='tugas'&&x.sourceId&&x.status==='selesai')){await db.ref(`${ROOT}/tasks/${i.sourceId}`).update({status:'selesai',updatedAt:nowIso(),updatedBy:createdMeta()});await db.ref(`${ROOT}/tasks_by_pic/${safeKey(username())}/${i.sourceId}`).update({status:'selesai',updatedAt:nowIso(),updatedBy:createdMeta()})}for(const i of items.filter(x=>x.status==='kendala'&&x.makeFollowup)){const fid=safeKey(`journal_${key}_${i.id}`),f={task:`Kendala jobdesk: ${i.title}`,sourceType:'jobdesk',sourceId:key,sourceTitle:i.title,division:currentDivision(),pic:username(),picName:displayName(),deadline:addDays(today(),2),priority:'sedang',status:'baru',description:i.note||'',createdAt:nowIso(),createdBy:createdMeta(),updatedAt:nowIso(),updatedBy:createdMeta()};await db.ref(`${ROOT}/followups/${fid}`).set(f);await db.ref(`${ROOT}/followups_by_pic/${safeKey(username())}/${fid}`).set(f)}todayJournal=payload;todayJobs=todayJobs.map(j=>({...j,status:items.find(i=>i.id===j.id)?.status||''}));await refreshPerformanceSummary(username(),activePosition,monthKey());deleteCache('tasks');deleteCache('followups');closeForm();toast('Jurnal pelaksanaan hari ini tersimpan.');renderTodayJobs()}finally{hideLoader()}}

  function renderCompetencies(){const q=String($('competencySearch')?.value||'').toLowerCase(),sf=$('competencyStatusFilter')?.value||'';const arr=scoped('competencies').filter(x=>(!sf||x.status===sf)&&(!q||[x.personName,x.competency,x.programType,x.notes,x.division].join(' ').toLowerCase().includes(q)));$('competencyList').innerHTML=arr.length?arr.map(x=>recordCard({chips:[statusChip(x.status),`<span class="chip purple">${esc(x.programType||'Pengembangan')}</span>`,x.groupId?`<span class="chip">Program Bersama</span>`:''],date:x.targetDate?`Target ${fmtDate(x.targetDate)}`:'',title:x.competency||'Pengembangan Kompetensi',desc:`${x.personName||x.person||'-'} • ${x.notes||''}`,foot:`<span>Pembina: ${esc(x.coachName||'-')}</span><select class="status-select" onclick="event.stopPropagation()" onchange="Operational.updateCompetencyStatus('${esc(x.id)}',this.value)"><option value="direncanakan" ${x.status==='direncanakan'?'selected':''}>Direncanakan</option><option value="berjalan" ${x.status==='berjalan'?'selected':''}>Berjalan</option><option value="pendampingan" ${x.status==='pendampingan'?'selected':''}>Perlu Pendampingan</option><option value="selesai" ${x.status==='selesai'?'selected':''}>Selesai</option></select>`})).join(''):empty('Belum ada program pengembangan kompetensi.')}
  function competencyTargetHtml(mode='person'){if(mode==='person')return `<div class="multi-person" id="competencyPeople">${permittedPeople(currentLevel()==='direktur').map(u=>{const un=usernameOf(u),p=bestPositionFor(un);return `<label class="person-check"><input type="checkbox" value="${esc(un)}"><span><b>${esc(nameOf(u))}</b><span>${esc(p?.title||'Personel')}</span></span></label>`}).join('')}</div>`;if(mode==='level')return `<select class="control" id="competencyTargetValue">${levelOptions(rankOf(currentLevel())<4?Object.keys(LEVELS)[Math.min(4,rankOf(currentLevel())+1)]:'staf-mula')}</select>`;return `<select class="control" id="competencyTargetValue">${divisionOptions(currentDivision(),false)}</select>`}
  function openCompetencyForm(){$('formKicker').textContent='PENGEMBANGAN KOMPETENSI';$('formTitle').textContent='Program Pengembangan';$('formBody').innerHTML=`<div class="form-grid"><div class="field"><label>Sasaran Program</label><select class="control" id="competencyTargetMode" onchange="Operational.renderCompetencyTarget()"><option value="person">Beberapa Personel</option><option value="level">Jabatan / Level</option><option value="division">Bidang / Tim</option></select></div><div class="field"><label>Jenis Program</label><select class="control" id="competencyType"><option>Coaching</option><option>Pelatihan</option><option>Mentoring</option><option>Microteaching</option><option>Observasi Terarah</option></select></div><div class="field full"><label>Pilih Sasaran</label><div id="competencyTargetBox">${competencyTargetHtml('person')}</div></div><div class="field full"><label>Kompetensi yang Dikembangkan</label><input class="control" id="competencyName" placeholder="Contoh: Manajemen Rapat, Delegasi, Supervisi..."></div><div class="field"><label>Target Selesai</label><input class="control" type="date" id="competencyTarget" value="${addDays(today(),30)}"></div><div class="field"><label>Status Awal</label><select class="control" id="competencyStatus"><option value="direncanakan">Direncanakan</option><option value="berjalan">Berjalan</option></select></div><div class="field full"><label>Target Perilaku / Catatan</label><textarea class="control" id="competencyNotes"></textarea></div></div><div class="form-actions"><button class="btn soft" onclick="Operational.closeForm()">Batal</button><button class="btn gold" onclick="Operational.saveCompetency()">Simpan Program</button></div>`;modalOpen('formModal')}
  function renderCompetencyTarget(){const mode=$('competencyTargetMode').value;$('competencyTargetBox').innerHTML=competencyTargetHtml(mode)}
  function competencyTargets(){const mode=$('competencyTargetMode').value;if(mode==='person')return [...document.querySelectorAll('#competencyPeople input:checked')].map(x=>x.value);const v=$('competencyTargetValue').value;if(mode==='level')return uniq(positions.filter(p=>p.level===v&&(currentLevel()==='direktur'||currentDivision()==='Semua Divisi'||p.division===currentDivision())).map(p=>p.username));return uniq(positions.filter(p=>p.division===v).map(p=>p.username))}
  async function saveCompetency(){const targets=competencyTargets(),name=$('competencyName').value.trim();if(!targets.length||!name){toast('Pilih sasaran dan kompetensi.');return}const groupId=db.ref(`${ROOT}/competency_groups`).push().key,common={groupId,programType:$('competencyType').value,competency:name,targetDate:$('competencyTarget').value,status:$('competencyStatus').value,notes:$('competencyNotes').value.trim(),coach:username(),coachName:displayName(),coachPosition:activePosition.title,createdAt:nowIso(),createdBy:createdMeta(),updatedAt:nowIso()};showLoader('Menyimpan program pengembangan...');try{for(const person of targets){const id=db.ref(`${ROOT}/competencies`).push().key,u=userByUsername(person),p=bestPositionFor(person),payload={...common,person,personName:nameOf(u)||person,division:p?.division||'',level:p?.level||'',positionTitle:p?.title||''};await db.ref(`${ROOT}/competencies/${id}`).set(payload);await db.ref(`${ROOT}/competencies_by_person/${safeKey(person)}/${id}`).set(payload);await notifyUser(person,'Program Pengembangan Kompetensi',`${displayName()} menetapkan pengembangan: ${name}`,'main-dashboard.html?operasional=competencies')}deleteCache('competencies');closeForm();toast(`Program diberikan kepada ${targets.length} personel.`)}finally{hideLoader()}}
  async function updateCompetencyStatus(id,status){const x=data.competencies.find(a=>a.id===id);await db.ref(`${ROOT}/competencies/${id}`).update({status,updatedAt:nowIso(),updatedBy:createdMeta()});if(x?.person)await db.ref(`${ROOT}/competencies_by_person/${safeKey(x.person)}/${id}`).update({status,updatedAt:nowIso(),updatedBy:createdMeta()});deleteCache('competencies');toast('Status pengembangan diperbarui.')}

  function deleteCache(prefix){Object.keys(cache).filter(k=>k.startsWith(prefix+':')).forEach(k=>delete cache[k])}
  async function notifyUser(user,title,desc,link){if(!user)return;try{await db.ref(`cahaya_app/notifikasi_user/${safeKey(user)}`).push().set({title,desc,link,dibaca:false,createdAt:nowIso(),source:'manajemen_operasional'})}catch(e){console.warn('Notifikasi:',e)}}

  async function init(){showLoader('Menyiapkan CAHAYA APP...');try{await loadFoundation();setupFilters();setupNav();let requested=new URLSearchParams(location.search).get('view')||location.hash.replace('#','')||'dashboard';if(!document.getElementById('view-'+requested))requested='dashboard';await navigate(requested,false)}catch(e){console.error(e);$('moduleSignals').innerHTML=empty('Manajemen Operasional belum dapat dimuat. Muat ulang halaman.');hideLoader()}}
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeForm();closeDetail()}});

  window.Operational={navigate,selectPosition,closeForm,closeDetail,openObjectiveForm,refreshObjectiveKpiFields,saveObjective,openTaskForm,saveTask,openTaskDetail,updateTaskStatus,openObservationForm,saveObservation,openObservationDetail,openMeetingForm,selectDefaultParticipants,refreshAgendaSuggestions,applyAgendaCandidates,addMeetingFollowRow,saveMeeting,openMeetingDetail,updateFollowupStatus,openReportForm,saveReport,openReportDetail,openJournalForm,saveJournal,openCompetencyForm,renderCompetencyTarget,saveCompetency,updateCompetencyStatus};
  init();
